// Build the SQL-writing prompt: schema + question, JSON-constrained output.
const question = $json.body?.question ?? $json.question;
if (!question) throw new Error('POST a JSON body with a "question" field');
const schema = `
campaigns(campaign_id, campaign_name, channel)  -- channel: paid_search|paid_social|email|organic
daily_performance(perf_date, campaign_id, revenue, spend, leads)`;
return [{ json: { question, prompt: `You write PostgreSQL for analysts. Schema:${schema}

Rules: SELECT-only. Single statement. Use ISO dates relative to CURRENT_DATE. Respond ONLY as JSON: {"sql": "..."}.

Question: ${question}` } }];

// Guardrail: the model's SQL must be a single SELECT — nothing else runs.
const out = JSON.parse($json.response);
const sql = String(out.sql ?? '').trim().replace(/;\s*$/, '');
const forbidden = /\b(insert|update|delete|drop|alter|create|grant|truncate|copy)\b|;/i;
if (!/^select\b/i.test(sql) || forbidden.test(sql)) {
  throw new Error(`Blocked non-SELECT SQL from model: ${sql.slice(0, 120)}`);
}
return [{ json: { sql, question: $('Build SQL Prompt').first().json.question } }];

// Second model call: narrate the rows. Numbers come from the DB, words from the model.
const rows = items.map(i => i.json);
const { question, sql } = $('Guardrail: SELECT-only').first().json;
return [{ json: { question, sql, rows,
  prompt: `Question: ${question}\nQuery result rows (JSON): ${JSON.stringify(rows).slice(0, 4000)}\n\nAnswer the question in 2-3 sentences using ONLY these rows. Include the key numbers. If rows are empty, say no data matched.` } }];
